requirement:
{
  "process_name": "Order to Cash (O2C)",
  "source_systems": ["SAP ECC/S4HANA"],
  "case_id_definition": "VBELN (Sales Order Header)",
  "activity_definitions": [
    {
      "name": "Create Sales Order",
      "trigger_condition": "New record in VBAK table"
    },
    {
      "name": "Create Sales Order Item",
      "trigger_condition": "New record in VBAP table"
    },
    {
      "name": "Change Sales Order",
      "trigger_condition": "CDHDR.OBJECTCLAS = 'VERKBELEG' and CDHDR.OBJECTID = VBAK.VBELN"
    },
    {
      "name": "Credit Check",
      "trigger_condition": "VBAK.KNKK credit exposure evaluation at time of creation"
    },
    {
      "name": "Record Goods Issue",
      "trigger_condition": "LIKP.WADAT_IST is populated and MSEG.BWART = '601'"
    },
    {
      "name": "Cancel Goods Issue",
      "trigger_condition": "MKPF.BUDAT where MSEG.BWART = '602'"
    },
    {
      "name": "Sales Order Status Change",
      "trigger_condition": "VBAK.GBSTK value transition (e.g., A to B or B to C)"
    }
  ],
  "key_timestamp_fields": [
    {
      "activity_name": "Create Sales Order",
      "source_field": "VBAK.ERDAT"
    },
    {
      "activity_name": "Change Sales Order",
      "source_field": "CDHDR.UDATE"
    },
    {
      "activity_name": "Record Goods Issue",
      "source_field": "LIKP.WADAT_IST"
    }
  ],
  "kpis": [
    {
      "name": "Cycle Time",
      "description": "Total time from Sales Order creation to Goods Issue",
      "calculation_idea": "AVG(LIKP.WADAT_IST - VBAK.ERDAT)"
    },
    {
      "name": "Rework Rate",
      "description": "Percentage of orders with at least one change document",
      "calculation_idea": "COUNT(CASE WHEN Change_Activity_Count > 0 THEN VBELN END) / COUNT(VBELN)"
    },
    {
      "name": "Goods Issue Reversal Rate",
      "description": "Frequency of GI cancellations",
      "calculation_idea": "COUNT(Cancel Goods Issue) / COUNT(Record Goods Issue)"
    }
  ],
  "business_filters": [
    {
      "name": "Exclude Canceled Orders",
      "rule": "VBAK.ABRVW != 'X' (or relevant cancellation indicator)"
    },
    {
      "name": "Filter by Sales Org",
      "rule": "VBAK.VKORG = 'Required_Value'"
    }
  ],
  "acceptance_rules": [
    "All Sales Orders must have a valid VBELN.",
    "Goods Issue date must be greater than or equal to Sales Order creation date.",
    "Status changes must follow logical progression (A -> B -> C)."
  ]
}

