{
  "process_name": "Order to Cash (O2C)",
  "source_systems": ["SAP ECC", "SAP S/4HANA"],
  "case_id_definition": "VBELN (Sales Order Header)",
  "activity_definitions": [
    {
      "name": "Create Sales Order",
      "trigger_condition": "New record in VBAK table (ERDAT)"
    },
    {
      "name": "Create Sales Order Item",
      "trigger_condition": "New record in VBAP table (ERDAT)"
    },
    {
      "name": "Change Sales Order",
      "trigger_condition": "CDHDR entry where OBJECTCLAS = 'VERKBELEG' and OBJECTID = VBELN"
    },
    {
      "name": "Credit Check",
      "trigger_condition": "VBAK.ERDAT where credit exposure (KNKK) is evaluated"
    },
    {
      "name": "Record Goods Issue",
      "trigger_condition": "LIKP.WADAT_IST populated and MSEG.BWART = 601"
    },
    {
      "name": "Cancel Goods Issue",
      "trigger_condition": "MKPF.BUDAT where MSEG.BWART = 602"
    },
    {
      "name": "Sales Order Status Change",
      "trigger_condition": "VBAK.GBSTK field value change"
    }
  ],
  "key_timestamp_fields": [
    {
      "activity_name": "Create Sales Order",
      "source_field": "VBAK.ERDAT"
    },
    {
      "activity_name": "Record Goods Issue",
      "source_field": "LIKP.WADAT_IST"
    },
    {
      "activity_name": "Sales Order Status Change",
      "trigger_condition": "VBAK.AEDAT"
    }
  ],
  "kpis": [
    {
      "name": "Cycle Time",
      "description": "Total time from Sales Order creation to Goods Issue",
      "calculation_idea": "AVG(LIKP.WADAT_IST - VBAK.ERDAT)"
    },
