{
  "key_performance_indicators": [
    {
      "id": "cycle_time_o2c",
      "name": "Average Cycle Time (SO to GI)",
      "formula": "AVG(CALC_THROUGHPUT(FIRST_OCCURRENCE['Create Sales Order'] TO LAST_OCCURRENCE['Record Goods Issue'], REMAP_TIMESTAMPS(\"O2C_EVENT_LOG\".\"EVENT_TIME\", DAYS)))",
      "description": "Average time in days from Sales Order creation to Goods Issue.",
      "unit": "Days"
    },
    {
      "id": "rework_rate",
      "name": "Rework Rate",
      "formula": "COUNT_TABLE(O2C_CASES) FILTER (FILTER_ACTIVITY('Change Sales Order')) / COUNT_TABLE(O2C_CASES)",
      "description": "Percentage of sales orders that underwent at least one change activity.",
      "unit": "%"
    }
  ],
  "custom_dimensions": [
    {
      "id": "sales_org",
      "name": "Sales Organization",
      "expression": "O2C_CASES.VKORG",
      "description": "The sales organization responsible for the order."
    },
    {
      "id": "doc_type",
      "name": "Document Type",
      "expression": "O2C_CASES.AUART",
      "description": "The sales document type (e.g., Standard Order, Rush Order)."
    }
  ],
  "process_filters": [
    {
      "id": "exclude_cancelled",
      "name": "Exclude Cancelled Orders",
      "filter_expression": "FILTER ISNULL(O2C_CASES.ABGRU)",
      "description": "Removes orders that have been marked as cancelled (ABGRU is not null)."
    }
  ],
  "business_entities": [
    {
      "name": "Sales Order",
      "description": "Core entity representing the customer order header.",
      "key_mappings": {
        "case_id": "O2C_CASES.VBELN"
      }
    },
    {
      "name": "Delivery",
      "description": "Logistics entity representing the goods issue process.",
      "key_mappings": {
        "case_id": "LIKP.VBELN"
      }
    }
  ]
}

