DROP TABLE IF EXISTS P2P_EVENT_LOG;
CREATE TABLE P2P_EVENT_LOG (
    CASE_ID VARCHAR(255),
    ACTIVITY VARCHAR(255),
    EVENT_TIME TIMESTAMP,
    USER_NAME VARCHAR(255),
    AMOUNT DECIMAL(15,2)
);

INSERT INTO P2P_EVENT_LOG
SELECT EBELN || '-' || EBELP AS CASE_ID, 'Create Purchase Requisition' AS ACTIVITY, COALESCE(TO_TIMESTAMP(NULLIF(TRIM(BADAT), ''), 'yyyy-MM-dd'), '1900-01-01'::TIMESTAMP) AS EVENT_TIME, AFNAM AS USER_NAME, 0.0 AS AMOUNT FROM EBAN WHERE EBELN IS NOT NULL;

INSERT INTO P2P_EVENT_LOG
SELECT EKPO.EBELN || '-' || EKPO.EBELP AS CASE_ID, 'Create Purchase Order Item' AS ACTIVITY, COALESCE(TO_TIMESTAMP(NULLIF(TRIM(EKKO.BEDAT), ''), 'yyyy-MM-dd'), '1900-01-01'::TIMESTAMP) AS EVENT_TIME, EKKO.ERNAM AS USER_NAME, COALESCE(NULLIF(TRIM(EKPO.NETWR), '')::DECIMAL(15,2), 0.0) AS AMOUNT FROM EKPO JOIN EKKO ON EKPO.EBELN = EKKO.EBELN WHERE EKPO.LOEKZ IS NULL;

INSERT INTO P2P_EVENT_LOG
SELECT CDHDR.OBJECTID AS CASE_ID, 'PO Approval Step' AS ACTIVITY, COALESCE(TO_TIMESTAMP(NULLIF(TRIM(CDHDR.UDATE), ''), 'yyyy-MM-dd'), '1900-01-01'::TIMESTAMP) AS EVENT_TIME, CDHDR.USERNAME AS USER_NAME, 0.0 AS AMOUNT FROM CDHDR WHERE CDHDR.OBJECTCLAS = 'EINKBELEG' AND CDHDR.CHANGENR IN (SELECT CHANGENR FROM CDPOS WHERE FNAME = 'FRGKE');

INSERT INTO P2P_EVENT_LOG
SELECT MSEG.EBELN || '-' || MSEG.EBELP AS CASE_ID, 'Record Goods Receipt' AS ACTIVITY, COALESCE(TO_TIMESTAMP(NULLIF(TRIM(MKPF.BUDAT), ''), 'yyyy-MM-dd'), '1900-01-01'::TIMESTAMP) AS EVENT_TIME, MKPF.USNAM AS USER_NAME, COALESCE(NULLIF(TRIM(MSEG.DMBTR), '')::DECIMAL(15,2), 0.0) AS AMOUNT FROM MSEG JOIN MKPF ON MSEG.MBLNR = MKPF.MBLNR WHERE MSEG.BWART = '101';

INSERT INTO P2P_EVENT_LOG
SELECT EBELN || '-' || EBELP AS CASE_ID, 'First Invoice Created' AS ACTIVITY, COALESCE(TO_TIMESTAMP(NULLIF(TRIM(BUDAT), ''), 'yyyy-MM-dd'), '1900-01-01'::TIMESTAMP) AS EVENT_TIME, NULL AS USER_NAME, COALESCE(NULLIF(TRIM(DMBTR), '')::DECIMAL(15,2), 0.0) AS AMOUNT FROM EKBE WHERE VGABE = '2';

INSERT INTO P2P_EVENT_LOG
SELECT EBELN || '-' || EBELP AS CASE_ID, 'Clear Invoice' AS ACTIVITY, COALESCE(TO_TIMESTAMP(NULLIF(TRIM(AUGDT), ''), 'yyyy-MM-dd'), '1900-01-01'::TIMESTAMP) AS EVENT_TIME, NULL AS USER_NAME, 0.0 AS AMOUNT FROM BSEG WHERE AUGBL IS NOT NULL AND NULLIF(TRIM(EBELN), '') IS NOT NULL;

INSERT INTO P2P_EVENT_LOG
SELECT CDHDR.OBJECTID AS CASE_ID, 'Change Price' AS ACTIVITY, COALESCE(TO_TIMESTAMP(NULLIF(TRIM(CDHDR.UDATE), ''), 'yyyy-MM-dd'), '1900-01-01'::TIMESTAMP) AS EVENT_TIME, CDHDR.USERNAME AS USER_NAME, 0.0 AS AMOUNT FROM CDHDR JOIN CDPOS ON CDHDR.CHANGENR = CDPOS.CHANGENR WHERE CDPOS.FNAME = 'NETPR';

DROP TABLE IF EXISTS P2P_CASES;
CREATE TABLE P2P_CASES AS
SELECT EKPO.EBELN || '-' || EKPO.EBELP AS CASE_ID, EKKO.BEDAT, EKKO.LIFNR, EKKO.EKORG, EKPO.MATNR, COALESCE(NULLIF(TRIM(EKPO.NETWR), '')::DECIMAL(15,2), 0.0) AS NETWR, EKKO.WAERS
FROM EKPO
JOIN EKKO ON EKPO.EBELN = EKKO.EBELN
WHERE EKPO.LOEKZ IS NULL
AND EKKO.BEDAT >= CURRENT_DATE - INTERVAL '24 months';

