{
  "case_table": "P2P_CASES",
  "event_table": "P2P_EVENT_LOG",
  "model_type": "Case-centric",
  "tables": [
    {
      "name": "P2P_CASES",
      "type": "Case",
      "primary_keys": ["CASE_ID"],
      "description": "Master table for P2P process cases defined by Purchase Order Item."
    },
    {
      "name": "P2P_EVENT_LOG",
      "type": "Event",
      "primary_keys": ["CASE_ID", "ACTIVITY", "EVENT_TIME"],
      "description": "Consolidated event log containing all P2P process activities."
    },
    {
      "name": "EKKO",
      "type": "Dimension",
      "primary_keys": ["EBELN"],
      "description": "Purchase Order Header data."
    },
    {
      "name": "EBAN",
      "type": "Dimension",
      "primary_keys": ["EBELN", "BNFPO"],
      "description": "Purchase Requisition data for cycle time analysis."
    },
    {
      "name": "EKBE",
      "type": "Dimension",
      "primary_keys": ["EBELN", "EBELP", "ZEKKN"],
      "description": "Purchase Order History (Goods Receipts and Invoices)."
    }
  ],
  "relationships": [
    {
      "source_table": "P2P_CASES",
      "target_table": "P2P_EVENT_LOG",
      "source_column": "CASE_ID",
      "target_column": "CASE_ID",
      "cardinality": "1:N"
    },
    {
      "source_table": "P2P_CASES",
      "target_table": "EKKO",
      "source_column": "CASE_ID",
      "target_column": "EBELN",
      "cardinality": "N:1"
    },
    {
      "source_table": "P2P_CASES",
      "target_table": "EBAN",
      "source_column": "CASE_ID",
      "target_column": "EBELN",
      "cardinality": "N:1"
    },
    {
      "source_table": "P2P_CASES",
      "target_table": "EKBE",
      "source_column": "CASE_ID",
      "target_column": "EBELN",
      "cardinality": "1:N"
    }
  ]
}

{
  "key_performance_indicators": [
    {
      "id": "touchless_invoice_rate",
      "name": "Touchless Invoice %",
      "formula": "1.0 - (COUNT_TABLE(P2P_CASES) FILTER (FILTER_ACTIVITY('Change Price') OR FILTER_ACTIVITY('Change Quantity')) / COUNT_TABLE(P2P_CASES))",
      "description": "Percentage of invoices processed without manual changes to price or quantity.",
      "unit": "%"
    },
    {
      "id": "no_touch_po_rate",
      "name": "No-Touch PO %",
      "formula": "COUNT_TABLE(P2P_CASES) FILTER (NOT FILTER_ACTIVITY('Change Purchase Order')) / COUNT_TABLE(P2P_CASES)",
      "description": "Percentage of POs created without any subsequent change activities.",
      "unit": "%"
    },
    {
      "id": "pr_to_po_cycle_time",
      "name": "PR-to-PO Cycle Time",
      "formula": "AVG(CALC_THROUGHPUT(FIRST_OCCURRENCE['Create Purchase Requisition'] TO FIRST_OCCURRENCE['Create Purchase Order Item'], REMAP_TIMESTAMPS(\"P2P_EVENT_LOG\".\"EVENT_TIME\", DAYS)))",
      "description": "Average time in days from PR creation to PO creation.",
      "unit": "Days"
    },
    {
      "id": "invoice_block_rate",
      "name": "Invoice Block Rate",
      "formula": "COUNT_TABLE(P2P_CASES) FILTER (FILTER_ACTIVITY('Payment Block')) / COUNT_TABLE(P2P_CASES)",
      "description": "Percentage of invoices that triggered a payment block activity.",
      "unit": "%"
    }
  ],
  "custom_dimensions": [
    {
      "id": "purchasing_org",
      "name": "Purchasing Organization",
      "expression": "EKKO.EKORG",
      "description": "The purchasing organization responsible for the PO."
    },
    {
      "id": "vendor_name",
      "name": "Vendor",
      "expression": "EKKO.LIFNR",
      "description": "The vendor associated with the purchase order."
    }
  ],
  "process_filters": [
    {
      "id": "maverick_buying",
      "name": "Maverick Buying",
      "filter_expression": "FILTER NOT FILTER_ACTIVITY('Create Purchase Requisition')",
      "description": "Filters for POs created without a preceding Purchase Requisition."
    },
    {
      "id": "duplicate_payment_risk",
      "name": "Duplicate Payment Risk",
      "filter_expression": "FILTER COUNT_TABLE(P2P_EVENT_LOG) FILTER (ACTIVITY = 'Clear Invoice') > 1",
      "description": "Filters for cases with multiple clearing documents."
    }
  ],
  "business_entities": [
    {
      "name": "Purchase Order Item",
      "description": "The core P2P case entity.",
      "key_mappings": {
        "case_id": "P2P_CASES.CASE_ID"
      }
    },
    {
      "name": "Purchase Order Header",
      "description": "Header level information for the PO.",
      "key_mappings": {
        "case_id": "EKKO.EBELN"
      }
    }
  ]
}

