requirement:
{
  "process_name": "Accounts Payable (FI-AP)",
  "source_systems": ["SAP ECC", "SAP S/4HANA"],
  "case_id_definition": "BELNR + BUKRS + GJAHR (Accounting Document Header where KOART = 'K')",
  "activity_definitions": [
    {"name": "Invoice Received", "trigger_condition": "RBKP.CPUDT (OCR/Entry date)"},
    {"name": "Create Invoice", "trigger_condition": "BKPF.BUDAT (First posting of document with BLART = RE/KR)"},
    {"name": "Set Payment Block", "trigger_condition": "CDHDR.UDATE where CDPOS.FNAME = 'ZLSPR' and VALUE_NEW is not empty"},
    {"name": "Release Payment Block", "trigger_condition": "CDHDR.UDATE where CDPOS.FNAME = 'ZLSPR' and VALUE_NEW is empty"},
    {"name": "Invoice Approved", "trigger_condition": "CDHDR.UDATE where status change in workflow tables (SWWWIHEAD)"},
    {"name": "Clear Invoice", "trigger_condition": "BSEG.AUGDT (BSEG.AUGBL is populated)"},
    {"name": "Check Issued", "trigger_condition": "PAYR.ZALDT (Payment run creation)"}
  ],
  "key_timestamp_fields": [
    {"activity_name": "Invoice Received", "source_field": "RBKP.CPUDT"},
    {"activity_name": "Create Invoice", "source_field": "BKPF.BUDAT"},
    {"activity_name": "Clear Invoice", "source_field": "BSEG.AUGDT"},
    {"activity_name": "Check Issued", "source_field": "PAYR.ZALDT"}
  ],
  "kpis": [
    {"name": "Touchless Rate", "description": "Percentage of invoices posted without manual intervention", "calculation_idea": "Count(Invoices with no manual activity) / Total Invoices"},
    {"name": "Cycle Time", "description": "Average time from receipt to payment", "calculation_idea": "Avg(Clear Date - Receipt Date)"},
    {"name": "Block Rate", "description": "Percentage of invoices subject to payment blocks", "calculation_idea": "Count(Invoices with ZLSPR set) / Total Invoices"},
    {"name": "On-Time Payment Rate", "description": "Percentage of payments made before due date", "calculation_idea": "Count(Payment Date <= Due Date) / Total Payments"}
  ],
  "business_filters": [
    {"name": "Duplicate Payments", "rule": "Group by Vendor, Amount, Currency, Date; Count > 1"},
    {"name": "SoD Violations", "rule": "User who created invoice (BKPF.USNAM) is same as user who approved invoice"}
  ],
  "acceptance_rules": [
    "20% improvement in Touchless Rate",
    "30% reduction in Cycle Time",
    "95% On-Time Payment Rate"
  ]
}

