DROP TABLE IF EXISTS P2P_EVENT_LOG;
CREATE TABLE P2P_EVENT_LOG (
    CASE_ID VARCHAR(255),
    ACTIVITY VARCHAR(255),
    EVENT_TIME TIMESTAMP,
    USER_NAME VARCHAR(255),
    AMOUNT DECIMAL(15,2)
);

-- Create Purchase Requisition
INSERT INTO P2P_EVENT_LOG
SELECT CONCAT(EBAN.EBELN, '-', EBAN.BNFPO) AS CASE_ID, 'Create Purchase Requisition' AS ACTIVITY, TO_TIMESTAMP(EBAN.BADAT, 'yyyy-MM-dd') AS EVENT_TIME, NULL AS USER_NAME, 0.0 AS AMOUNT
FROM EBAN WHERE EBAN.EBELN IS NOT NULL AND EBAN.BADAT IS NOT NULL AND TRIM(EBAN.BADAT) <> '';

-- Create Purchase Order Item
INSERT INTO P2P_EVENT_LOG
SELECT CONCAT(EKPO.EBELN, '-', EKPO.EBELP) AS CASE_ID, 'Create Purchase Order Item' AS ACTIVITY, TO_TIMESTAMP(EKKO.BEDAT, 'yyyy-MM-dd') AS EVENT_TIME, EKKO.ERNAM AS USER_NAME, COALESCE(EKPO.NETWR, 0.0) AS AMOUNT
FROM EKPO JOIN EKKO ON EKPO.EBELN = EKKO.EBELN WHERE EKKO.LOEKZ IS NULL AND EKPO.LOEKZ IS NULL AND EKKO.BEDAT IS NOT NULL;

-- Record Goods Receipt
INSERT INTO P2P_EVENT_LOG
SELECT CONCAT(MSEG.EBELN, '-', MSEG.EBELP) AS CASE_ID, 'Record Goods Receipt' AS ACTIVITY, TO_TIMESTAMP(MKPF.BUDAT, 'yyyy-MM-dd') AS EVENT_TIME, MKPF.USNAM AS USER_NAME, COALESCE(MSEG.MENGE, 0.0) AS AMOUNT
FROM MSEG JOIN MKPF ON MSEG.MBLNR = MKPF.MBLNR AND MSEG.MJAHR = MKPF.MJAHR WHERE MSEG.BWART = '101' AND MSEG.EBELN IS NOT NULL AND MKPF.BUDAT IS NOT NULL;

-- First Invoice Created
INSERT INTO P2P_EVENT_LOG
SELECT CONCAT(EKBE.EBELN, '-', EKBE.EBELP) AS CASE_ID, 'First Invoice Created' AS ACTIVITY, MIN(TO_TIMESTAMP(EKBE.BUDAT, 'yyyy-MM-dd')) AS EVENT_TIME, NULL AS USER_NAME, SUM(COALESCE(EKBE.WRBTR, 0.0)) AS AMOUNT
FROM EKBE WHERE EKBE.VGABE = '2' AND EKBE.EBELN IS NOT NULL AND EKBE.BUDAT IS NOT NULL GROUP BY EKBE.EBELN, EKBE.EBELP;

-- Clear Invoice
INSERT INTO P2P_EVENT_LOG
SELECT CONCAT(BSEG.EBELN, '-', BSEG.EBELP) AS CASE_ID, 'Clear Invoice' AS ACTIVITY, TO_TIMESTAMP(BSEG.AUGDT, 'yyyy-MM-dd') AS EVENT_TIME, NULL AS USER_NAME, COALESCE(BSEG.DMBTR, 0.0) AS AMOUNT
FROM BSEG WHERE BSEG.AUGBL IS NOT NULL AND BSEG.AUGDT IS NOT NULL AND BSEG.EBELN IS NOT NULL AND BSEG.EBELP IS NOT NULL;

-- Change Purchase Order (Generic)
INSERT INTO P2P_EVENT_LOG
SELECT CONCAT(CDHDR.OBJECTID, '-', '00001') AS CASE_ID, 'Change Purchase Order' AS ACTIVITY, TO_TIMESTAMP(CDHDR.UDATE, 'yyyy-MM-dd') AS EVENT_TIME, CDHDR.USERNAME AS USER_NAME, 0.0 AS AMOUNT
FROM CDHDR WHERE CDHDR.OBJECTCLAS = 'EINKBELEG' AND CDHDR.UDATE IS NOT NULL;

-- Payment Block
INSERT INTO P2P_EVENT_LOG
SELECT CONCAT(BSEG.EBELN, '-', BSEG.EBELP) AS CASE_ID, 'Payment Block' AS ACTIVITY, TO_TIMESTAMP(CDHDR.UDATE, 'yyyy-MM-dd') AS EVENT_TIME, CDHDR.USERNAME AS USER_NAME, 0.0 AS AMOUNT
FROM CDHDR JOIN CDPOS ON CDHDR.CHANGENR = CDPOS.CHANGENR JOIN BSEG ON CDHDR.OBJECTID = BSEG.BELNR WHERE CDPOS.FNAME = 'ZLSPR' AND CDPOS.VALUE_NEW <> '';

