{
  "key_performance_indicators": [
    {
      "id": "touchless_invoice_rate",
      "name": "Touchless Invoice %",
      "formula": "COUNT_TABLE(P2P_CASES) FILTER (NOT FILTER_ACTIVITY('Change Price') AND NOT FILTER_ACTIVITY('Change Quantity')) / COUNT_TABLE(P2P_CASES)",
      "description": "Percentage of invoices processed without manual price or quantity changes.",
      "unit": "%"
    },
    {
      "id": "no_touch_po_rate",
      "name": "No-Touch PO %",
      "formula": "COUNT_TABLE(P2P_CASES) FILTER (NOT FILTER_ACTIVITY('Change Purchase Order')) / COUNT_TABLE(P2P_CASES)",
      "description": "PO items created without manual changes.",
      "unit": "%"
    },
    {
      "id": "pr_to_po_cycle_time",
      "name": "PR-to-PO Cycle Time",
      "formula": "AVG(CALC_THROUGHPUT(FIRST_OCCURRENCE['Create Purchase Requisition'] TO FIRST_OCCURRENCE['Create Purchase Order Item'], REMAP_TIMESTAMPS(\"P2P_EVENT_LOG\".\"EVENT_TIME\", DAYS)))",
      "description": "Average time elapsed from PR creation to PO creation.",
      "unit": "Days"
    },
    {
      "id": "dpo",
      "name": "DPO",
      "formula": "AVG(CALC_THROUGHPUT(FIRST_OCCURRENCE['First Invoice Created'] TO FIRST_OCCURRENCE['Clear Invoice'], REMAP_TIMESTAMPS(\"P2P_EVENT_LOG\".\"EVENT_TIME\", DAYS)))",
      "description": "Average time from Invoice Receipt to Payment.",
      "unit": "Days"
    },
    {
      "id": "invoice_block_rate",
      "name": "Invoice Block Rate",
      "formula": "COUNT_TABLE(P2P_CASES) FILTER (FILTER_ACTIVITY('Payment Block')) / COUNT_TABLE(P2P_CASES)",
      "description": "Percentage of invoices blocked for payment.",
      "unit": "%"
    }
  ],
  "custom_dimensions": [
    {
      "id": "purchasing_org",
      "name": "Purchasing Organization",
      "expression": "EKKO.EKORG",
      "description": "The purchasing organization responsible for the PO."
    },
    {
      "id": "material_group",
      "name": "Material Group",
      "expression": "EKPO.MATKL",
      "description": "The material group assigned to the PO item."
    },
    {
      "id": "vendor",
      "name": "Vendor",
      "expression": "EKKO.LIFNR",
      "description": "The vendor associated with the purchase order."
    }
  ],
  "process_filters": [
    {
      "id": "maverick_buying",
      "name": "Maverick Buying",
      "filter_expression": "FILTER ISNULL(EBAN.BNFPO)",
      "description": "PO created without reference to a Purchase Requisition."
    },
    {
      "id": "duplicate_payments",
      "name": "Duplicate Payments",
      "filter_expression": "FILTER COUNT(BSEG.AUGBL) OVER (PARTITION BY BSEG.BELNR) > 1",
      "description": "Multiple payments for the same invoice reference number."
    }
  ],
  "business_entities": [
    {
      "name": "Purchase Order Item",
      "description": "The core P2P case entity defined by EBELN and EBELP.",
      "key_mappings": {
        "case_id": "P2P_CASES.CASE_ID"
      }
    }
  ]
}

DROP TABLE IF EXISTS P2P_EVENT_LOG;
CREATE TABLE P2P_EVENT_LOG (
    CASE_ID VARCHAR(255),
    ACTIVITY VARCHAR(255),
    EVENT_TIME TIMESTAMP,
    USER_NAME VARCHAR(255),
    AMOUNT DECIMAL(15,2)
);

-- Create Purchase Requisition
INSERT INTO P2P_EVENT_LOG
SELECT CONCAT(EBAN.EBELN, '-', EBAN.BNFPO) AS CASE_ID, 'Create Purchase Requisition' AS ACTIVITY, TO_TIMESTAMP(EBAN.BADAT, 'yyyy-MM-dd') AS EVENT_TIME, NULL AS USER_NAME, 0.0 AS AMOUNT
FROM EBAN WHERE EBAN.EBELN IS NOT NULL AND EBAN.BNFPO IS NOT NULL AND EBAN.BADAT IS NOT NULL AND TRIM(EBAN.BADAT) <> '';

-- Create Purchase Order Item
INSERT INTO P2P_EVENT_LOG
SELECT CONCAT(EKPO.EBELN, '-', EKPO.EBELP) AS CASE_ID, 'Create Purchase Order Item' AS ACTIVITY, TO_TIMESTAMP(EKKO.BEDAT, 'yyyy-MM-dd') AS EVENT_TIME, EKKO.ERNAM AS USER_NAME, COALESCE(NULLIF(TRIM(EKPO.NETWR), '')::DECIMAL(15,2), 0.0) AS AMOUNT
FROM EKPO JOIN EKKO ON EKPO.EBELN = EKKO.EBELN WHERE EKKO.LOEKZ IS NULL AND EKPO.LOEKZ IS NULL AND EKKO.BEDAT IS NOT NULL;

-- Record Goods Receipt
INSERT INTO P2P_EVENT_LOG
SELECT CONCAT(MSEG.EBELN, '-', MSEG.EBELP) AS CASE_ID, 'Record Goods Receipt' AS ACTIVITY, TO_TIMESTAMP(MKPF.BUDAT, 'yyyy-MM-dd') AS EVENT_TIME, MKPF.USNAM AS USER_NAME, COALESCE(NULLIF(TRIM(MSEG.MENGE), '')::DECIMAL(15,2), 0.0) AS AMOUNT
FROM MSEG JOIN MKPF ON MSEG.MBLNR = MKPF.MBLNR AND MSEG.MJAHR = MKPF.MJAHR WHERE MSEG.BWART = '101' AND MSEG.EBELN IS NOT NULL AND MSEG.EBELP IS NOT NULL AND MKPF.BUDAT IS NOT NULL;

-- First Invoice Created
INSERT INTO P2P_EVENT_LOG
SELECT CONCAT(EKBE.EBELN, '-', EKBE.EBELP) AS CASE_ID, 'First Invoice Created' AS ACTIVITY, MIN(TO_TIMESTAMP(EKBE.BUDAT, 'yyyy-MM-dd')) AS EVENT_TIME, NULL AS USER_NAME, SUM(COALESCE(NULLIF(TRIM(EKBE.WRBTR), '')::DECIMAL(15,2), 0.0)) AS AMOUNT
FROM EKBE WHERE EKBE.VGABE = '2' AND EKBE.EBELN IS NOT NULL AND EKBE.EBELP IS NOT NULL AND EKBE.BUDAT IS NOT NULL GROUP BY EKBE.EBELN, EKBE.EBELP;

-- Clear Invoice
INSERT INTO P2P_EVENT_LOG
SELECT CONCAT(BSEG.EBELN, '-', BSEG.EBELP) AS CASE_ID, 'Clear Invoice' AS ACTIVITY, TO_TIMESTAMP(BSEG.AUGDT, 'yyyy-MM-dd') AS EVENT_TIME, NULL AS USER_NAME, COALESCE(NULLIF(TRIM(BSEG.DMBTR), '')::DECIMAL(15,2), 0.0) AS AMOUNT
FROM BSEG WHERE BSEG.AUGBL IS NOT NULL AND TRIM(BSEG.AUGBL) <> '' AND BSEG.AUGDT IS NOT NULL AND BSEG.EBELN IS NOT NULL AND BSEG.EBELP IS NOT NULL;

-- Change Price / Quantity / Vendor (Generic Change Tracking)
INSERT INTO P2P_EVENT_LOG
SELECT CONCAT(CDHDR.OBJECTID, '-', '00001') AS CASE_ID, 'Change Activity' AS ACTIVITY, TO_TIMESTAMP(CDHDR.UDATE, 'yyyy-MM-dd') AS EVENT_TIME, CDHDR.USERNAME AS USER_NAME, 0.0 AS AMOUNT
FROM CDHDR JOIN CDPOS ON CDHDR.CHANGENR = CDPOS.CHANGENR WHERE CDHDR.OBJECTCLAS = 'EINKBELEG' AND CDPOS.FNAME IN ('NETPR', 'MENGE', 'LIFNR') AND CDHDR.UDATE IS NOT NULL;

